patch:
--- a/Source/FPSGAME/Production/ProductionTreeGrowthPresentation.cpp
+++ b/Source/FPSGAME/Production/ProductionTreeGrowthPresentation.cpp
@@ -44,8 +44,14 @@
     TArray<FTemperatePlacement> Wanted;
     constexpr double Radius=25600; // bounded local presentation for recurrent trees
     const auto Observers=ProductionObservers::Gather(GetWorld(),Eye);TSet<uint64> Seen;
-    for(const auto& View:Observers){TArray<FTemperatePlacement> Near;Hills->GetRegrowingTrees(FBox(View-FVector(Radius,Radius,50000),View+FVector(Radius,Radius,50000)),Near);
-        for(const auto& P:Near)if(!Seen.Contains(P.CandidateId)){Seen.Add(P.CandidateId);Wanted.Add(P);}}
+    for(const auto& View:Observers)
+    {
+        const FBox Bounds(View-FVector(Radius,Radius,50000),View+FVector(Radius,Radius,50000));
+        TArray<FTemperatePlacement> Near;
+        Hills->GetRegrowingTrees(Bounds,Near);
+        if(Hills->IsForestVillage())Hills->GetForestStandingTrees(Bounds,Near);
+        for(const auto& P:Near)if(!Seen.Contains(P.CandidateId)){Seen.Add(P.CandidateId);Wanted.Add(P);}
+    }
     Wanted.RemoveAll([&](const auto& P){return ProductionObservers::Distance(Observers,P.Transform.GetLocation())>Radius*Radius;});
     Wanted.Sort([&](const auto& A,const auto& B){return ProductionObservers::Distance(Observers,A.Transform.GetLocation())<ProductionObservers::Distance(Observers,B.Transform.GetLocation());});
     TSet<uint64> Keys;for(const auto& P:Wanted)Keys.Add(P.CandidateId);
@@ -68,6 +74,7 @@
         }
     }
     // Only transformed instances are updated. Ordinary PCG trees are never regenerated.
+    const int32 AddBudget=Hills->IsForestVillage()?48:8;
     int32 Added=0;
     for(const auto& P:Wanted)
     {
@@ -77,7 +84,7 @@
             {GrowthMeshes[Entry->Variant]->UpdateInstance(Entry->Id,P.Transform,0,true);Entry->Transform=P.Transform;}
             continue;
         }
-        if(Added>=8)continue;
+        if(Added>=AddBudget)continue;
         const int32 Variant=Hills->Assets->Trees.IndexOfByPredicate([&](const auto& T){return T.ToSoftObjectPath()==P.Mesh;});
         if(!GrowthMeshes.IsValidIndex(Variant))continue;
         const auto Id=GrowthMeshes[Variant]->AddInstance(P.Transform,0,true);
